#!/bin/bash
extract_patch_author() {
    local author=$(head -n 6 "$1" | grep 'From:' | sed 's/From: //')
    echo "${author:-$CVE_GIT_AUTHOR}"
}
extract_patch_date() {
    local date=$(head -n 6 "$1" | grep 'Date:' | sed 's/Date: //')
    echo "${date:-$(date)}"
}
extract_patch_subject() {
    local subject=$(head -n 6 "$1" | grep 'Subject:' | sed -E 's/Subject: (\[PATCH\] )?//')
    local pname=$(get_patch_name "$1")
    echo -e "${subject:-$pname}\n\napplied by CVE kernel patcher:\n${DOS_PATCHER_URI_KERNEL}/$pname"
}
get_patch_name() {
    local patch_path="$1"
    IFS='/' read -r -a parts <<< "$patch_path"
    local len=${#parts[@]}
    if (( len >= 3 )); then
        echo "${parts[len-3]}/${parts[len-2]}/${parts[len-1]}"
    else
        echo "$patch_path"
    fi
}
